reference_solution.python:
class Solution:
    def maxScore(self, cardPoints: List[int], k: int) -> int:
        total = sum(cardPoints)
        window = len(cardPoints) - k
        curr_sum = sum(cardPoints[:window])
        min_sum = curr_sum
        for i in range(window, len(cardPoints)):
            curr_sum += cardPoints[i] - cardPoints[i - window]
            min_sum = min(min_sum, curr_sum)
        return total - min_sum

reference_solution.javascript:
function maxScore(cardPoints, k) {
    const total = cardPoints.reduce((a,b) => a+b, 0);
    const window = cardPoints.length - k;
    let currSum = cardPoints.slice(0, window).reduce((a,b) => a+b, 0);
    let minSum = currSum;
    for (let i = window; i < cardPoints.length; i++) {
        currSum += cardPoints[i] - cardPoints[i - window];
        minSum = Math.min(minSum, currSum);
    }
    return total - minSum;
}
